head.script:
scwin.screenId = "jldods16001";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_disclsUser", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "disclsUser" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("disclsUser"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "disclsUser" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("disclsUser")))).length === 0)); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_20", entity: "dlt_disclsUser", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return String(v("title")); } }, { childId: "__rc1", fn: function (v, i) { return String(v("chrgNm")); } }, { childId: "__rc2", fn: function (v, i) { return String(v("depNm")); } }, { childId: "__rc3", fn: function (v, i) { return String(v("jobtitlNm")); } }, { childId: "__rc4", fn: function (v, i) { return String(v("telNo")); } }, { childId: "__rc5", fn: function (v, i) { return String(v("encrypCellphoneNo")); } }, { childId: "__rc6", fn: function (v, i) { return String(v("faxNo")); } }, { childId: "__rc7", fn: function (v, i) { return String(v("encrypEmail")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)
/**
 * @method
 * @name scwin.init_sessionFill
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_sessionFill = function () {
    const names = ["kclicUsrTpId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldods16001' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods16001.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/usradm/user.do?method=readUserDetail&integUsrId=",
        ref: "dma_loadListReq",
        target: "dlt_disclsUser=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods16001.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.list = function () {
    /* sdd-asis-lifecycle:begin fn_list — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ((String((((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.kclicUsrTpId", unresolved: "session:" + "kclicUsrTpId" }; })())($c.session.getUserInfo("kclicUsrTpId"))) == null ? '' : (((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.kclicUsrTpId", unresolved: "session:" + "kclicUsrTpId" }; })())($c.session.getUserInfo("kclicUsrTpId")))).indexOf('$' + '{') >= 0 ? '' : String((((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.kclicUsrTpId", unresolved: "session:" + "kclicUsrTpId" }; })())($c.session.getUserInfo("kclicUsrTpId"))) == null ? '' : (((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.kclicUsrTpId", unresolved: "session:" + "kclicUsrTpId" }; })())($c.session.getUserInfo("kclicUsrTpId"))))) === 'LIST_CORP_DISCLS') {
        $('#ipt_SCREN_ID', $('#searchForm')).val("/uldods17001/uldods17001.xml");
    } else {
        $('#ipt_SCREN_ID', $('#searchForm')).val("/uldods17000/uldods17000.xml");
    }
    $('#ipt_SCREN_PROCES_TP_CD', $('#searchForm')).val("01");
    $('#ipt_method', $('#searchForm')).val("readUserList");
    $('#searchForm').submit();
    /* sdd-asis-lifecycle:end */
};
